import { describe, it, expect } from 'vitest';
import { loadRecord, LoadError } from './loader';
import { TransformResult } from './types';

describe('loader', () => {
  const sampleRecord: TransformResult = {
    id: 100,
    slug: 'sample-record',
    sourceUrl: 'https://api.example.com/items/100',
    transformedAt: new Date().toISOString(),
  };

  it('successfully loads record into database table', async () => {
    const result = await loadRecord('analytics_events', sampleRecord);

    expect(result).toBeDefined();
    expect(result.success).toBe(true);
    expect(result.insertedId).toBe(100);
    expect(result.table).toBe('analytics_events');
  });

  it('fails with LoadError on duplicate key violation', async () => {
    const duplicateRecord: TransformResult = {
      ...sampleRecord,
      id: -1,
    };

    try {
      await loadRecord('analytics_events', duplicateRecord);
      expect.unreachable('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('analytics_events');
      expect(loadErr.tableName).toBe('analytics_events');
      expect(loadErr.operation).toBe('insert');
      expect(loadErr.message).toContain('Duplicate key violation');
      expect(loadErr.message).toContain('-1');
    }
  });

  it('fails with LoadError on database connection error', async () => {
    try {
      await loadRecord('connection_error_table', sampleRecord);
      expect.unreachable('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('connection_error_table');
      expect(loadErr.operation).toBeDefined();
      expect(loadErr.message).toMatch(/connection error/i);
    }

    // Also verify via simulateConnectionError option
    try {
      await loadRecord('users', sampleRecord, { simulateConnectionError: true });
      expect.unreachable('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('users');
      expect(loadErr.message).toMatch(/connection error/i);
    }
  });

  it('fails with LoadError on missing table name', async () => {
    try {
      await loadRecord('', sampleRecord);
      expect.unreachable('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.message).toContain('Missing destination table name');
    }
  });
});

