import { TransformResult, LoadResult, LoadError } from './types';

export type { LoadResult };
export { LoadError };

export interface LoadOptions {
  operation?: string;
  simulateConnectionError?: boolean;
}

export async function loadRecord(
  tableName: string,
  record: TransformResult,
  optionsOrCallback?: LoadOptions | ((err: Error | null, result?: LoadResult) => void),
  maybeCallback?: (err: Error | null, result?: LoadResult) => void
): Promise<LoadResult> {
  const options: LoadOptions =
    typeof optionsOrCallback === 'object' && optionsOrCallback !== null
      ? optionsOrCallback
      : {};
  const callback =
    typeof optionsOrCallback === 'function' ? optionsOrCallback : maybeCallback;

  const operation = options.operation ?? 'insert';

  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        if (!tableName || tableName.trim() === '') {
          throw new LoadError('Missing destination table name', tableName || '', operation);
        }

        if (
          options.simulateConnectionError ||
          tableName.includes('connection_error') ||
          tableName.includes('disconnect') ||
          tableName.includes('conn_err') ||
          (record.slug && record.slug.includes('connection-error'))
        ) {
          throw new LoadError(
            `Database connection error while accessing table "${tableName}"`,
            tableName,
            options.operation ?? 'connect'
          );
        }

        if (record.id < 0) {
          throw new LoadError(
            `Duplicate key violation in table ${tableName}: ${record.id}`,
            tableName,
            operation
          );
        }

        const result: LoadResult = {
          insertedId: record.id,
          table: tableName,
          success: true,
        };

        callback?.(null, result);
        resolve(result);
      } catch (err) {
        callback?.(err as Error);
        reject(err);
      }
    }, 10);
  });
}

export const load = loadRecord;

