import { describe, it, expect, vi, beforeEach } from 'vitest';
import { fetchUrl, FetchError, resetTransientAttempts } from './fetcher';

describe('fetcher', () => {
  beforeEach(() => {
    resetTransientAttempts();
  });

  it('successfully fetches data from a valid URL', async () => {
    const url = 'https://api.example.com/items';
    const result = await fetchUrl(url);

    expect(result).toBeDefined();
    expect(result.status).toBe(200);
    expect(result.url).toBe(url);

    const parsed = JSON.parse(result.data);
    expect(parsed.name).toBe('Sample Payload');
    expect(parsed.id).toBe(1);
    expect(parsed.url).toBe(url);
  });

  it('retries on 503 and recovers successfully', async () => {
    const onRetry = vi.fn();
    const url = 'https://api.example.com/transient-503-service';

    const result = await fetchUrl(url, {
      failAttempts: 1,
      backoffMs: 5,
      onRetry,
    });

    expect(result.status).toBe(200);
    expect(onRetry).toHaveBeenCalledTimes(1);
    expect(onRetry).toHaveBeenCalledWith(1, expect.any(FetchError));
    const retryError = onRetry.mock.calls[0][1] as FetchError;
    expect(retryError.status).toBe(503);
  });

  it('gives up after 3 retries on persistent 503 error', async () => {
    const onRetry = vi.fn();
    const url = 'https://api.example.com/503-service';

    try {
      await fetchUrl(url, {
        retries: 3,
        backoffMs: 5,
        onRetry,
      });
      expect.fail('Should have thrown FetchError');
    } catch (err) {
      expect(err).toBeInstanceOf(FetchError);
      const fetchErr = err as FetchError;
      expect(fetchErr.status).toBe(503);
      expect(fetchErr.url).toBe(url);
      expect(onRetry).toHaveBeenCalledTimes(3);
    }
  });

  it('handles request timeout properly', async () => {
    const url = 'https://api.example.com/timeout';

    try {
      await fetchUrl(url, {
        timeoutMs: 25,
        retries: 0,
      });
      expect.fail('Should have timed out');
    } catch (err) {
      expect(err).toBeInstanceOf(FetchError);
      const fetchErr = err as FetchError;
      expect(fetchErr.status).toBe(408);
      expect(fetchErr.message).toMatch(/timeout/i);
      expect(fetchErr.url).toBe(url);
    }
  });
});

