    expect(result.load.success).toBe(true);
    expect(result.load.insertedId).toBe(1);
    expect(result.load.table).toBe('items_table');
  });

  it('fails with PipelineError / PipelineStageError at fetch stage on invalid URL', async () => {
    await expect(
      runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      })
    ).rejects.toThrow(PipelineError);

    try {
      await runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
      expect(pipelineErr.cause).toBeDefined();
    }
  });

  it('fails with PipelineError at fetch stage on 500 error URL', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/error',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('HTTP 500');
    }
  });

  it('fails with PipelineError at transform stage if data transformation fails', async () => {
    const transformer = await import('./transformer');
    const spy = vi.spyOn(transformer, 'transformData').mockRejectedValueOnce(new Error('Invalid payload structure'));

    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('transform');
      expect(pipelineErr.message).toContain('Transform stage failed: Invalid payload structure');
    } finally {
      spy.mockRestore();
    }
  });

  it('fails with PipelineError at load stage on missing table name', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: '',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('load');
      expect(pipelineErr.message).toContain('Missing destination table name');
    }
  });
});

