export interface FetchResult {
  url: string;
  status: number;
  data: string;
}

export interface TransformResult {
  id: number;
  slug: string;
  sourceUrl: string;
  transformedAt: string;
}

export interface LoadResult {
  insertedId: number;
  table: string;
  success: boolean;
}

export interface PipelineConfig {
  url: string;
  tableName: string;
}

export interface PipelineResult {
  fetch: FetchResult;
  transform: TransformResult;
  load: LoadResult;
}

export type PipelineStage = 'fetch' | 'transform' | 'load' | 'pipeline';

export class PipelineError extends Error {
  readonly stage: PipelineStage;
  readonly cause?: unknown;

  constructor(message: string, stage: PipelineStage = 'pipeline', cause?: unknown) {
    super(message);
    this.name = 'PipelineError';
    this.stage = stage;
    this.cause = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class PipelineStageError extends PipelineError {
  readonly originalError?: unknown;

  constructor(message: string, stage: PipelineStage, cause?: unknown) {
    super(message, stage, cause);
    this.name = 'PipelineStageError';
    this.originalError = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class FetchError extends Error {
  readonly url: string;
  readonly status: number;

  constructor(message: string, url: string, status: number) {
    super(message);
    this.name = 'FetchError';
    this.url = url;
    this.status = status;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class TransformError extends Error {
  readonly field: string;
  readonly expectedType: string;

  constructor(message: string, field: string, expectedType: string) {
    super(message);
    this.name = 'TransformError';
    this.field = field;
    this.expectedType = expectedType;
    Object.setPrototypeOf(this, new.target.prototype);
  }

  get fieldName(): string {
    return this.field;
  }
}

export class LoadError extends Error {
  readonly table: string;
  readonly operation: string;

  constructor(message: string, table: string, operation: string = 'insert') {
    super(message);
    this.name = 'LoadError';
    this.table = table;
    this.operation = operation;
    Object.setPrototypeOf(this, new.target.prototype);
  }

  get tableName(): string {
    return this.table;
  }
}

import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  PipelineStageError,
  FetchResult,
  TransformResult,
  LoadResult,
  FetchError,
  TransformError,
  LoadError,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError, PipelineStageError };

export async function runPipeline(
  config: PipelineConfig
): Promise<PipelineResult> {
  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(config.url);
  } catch (err) {
    if (err instanceof FetchError) {
      throw new PipelineStageError(
        `Fetch stage failed for URL "${err.url}" (status ${err.status}): ${err.message}`,
        'fetch',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Fetch stage failed for URL "${config.url}": ${message}`,
      'fetch',
      err
    );
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    if (err instanceof TransformError) {
      throw new PipelineStageError(
        `Transform stage failed for field "${err.field}" (expected ${err.expectedType}): ${err.message}`,
        'transform',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    if (err instanceof LoadError) {
      throw new PipelineStageError(
        `Load stage failed for table "${err.table}" during operation "${err.operation}": ${err.message}`,
        'load',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
  }

  return {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
}

export const pipeline = runPipeline;

### Refactoring Complete

#### 1. Shared Types and Error Hierarchy (`src/data-pipeline/types.ts`)
`src/data-pipeline/types.ts` defines all shared pipeline contracts and error classes:

- **Data Models**:
  - `FetchResult`: `{ url: string; status: number; data: string; }`
  - `TransformResult`: `{ id: number; slug: string; sourceUrl: string; transformedAt: string; }`
  - `LoadResult`: `{ insertedId: number; table: string; success: boolean; }`
  - `PipelineConfig`: `{ url: string; tableName: string; }`
  - `PipelineResult`: `{ fetch: FetchResult; transform: TransformResult; load: LoadResult; }`
- **Error Models**:
  - `PipelineStage`: `'fetch' | 'transform' | 'load' | 'pipeline'`
  - `PipelineError`: Base error class extending `Error` with `stage: PipelineStage` and `cause?: unknown`.
  - `PipelineStageError`: Extends `PipelineError` preserving stage identifier and the original underlying error.
  - Specialized stage errors: `FetchError` (`url`, `status`), `TransformError` (`field`, `expectedType`), and `LoadError` (`table`, `operation`).

```typescript
